export function LineHeight({
  lineHeight = {{lineHeight}},
  fontSize = {{fontSize}},
  text = "{{text}}",
  background = "{{background}}",
}) {
  return (
    <div style={{ font: "14px/1.5 system-ui, sans-serif", color: "#241430", width: 300 }}>
      <p style={{ margin: 0, padding: 8, borderRadius: 6, lineHeight, fontSize, background: `${background}55` }}>{text}</p>
      <p style={{ marginTop: 12, fontSize: 12, color: "#241430cc" }}>line-height: {lineHeight}</p>
    </div>
  );
}
